package at.werkstatt.crm.gen;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyLong;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doNothing;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import at.werkstatt.crm.controller.AuftragController;
import at.werkstatt.crm.model.Auftrag;
import at.werkstatt.crm.model.AuftragPosition;
import at.werkstatt.crm.service.WerkstattService;
import java.util.Collections;
import java.util.List;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

@ExtendWith(MockitoExtension.class)
class AuftragControllerGeneratedTest {

    @Mock
    private WerkstattService werkstattService;

    private AuftragController controller;

    @BeforeEach
    void setUp() {
        controller = new AuftragController(werkstattService);
    }

    @Test
    void liste_returnsAuftraegeFromService_withStatus() {
        List<Auftrag> expected = List.of(mock(Auftrag.class));
        when(werkstattService.getAuftraege("ANGENOMMEN")).thenReturn(expected);

        List<Auftrag> result = controller.liste("ANGENOMMEN");

        assertThat(result).isEqualTo(expected);
        verify(werkstattService).getAuftraege("ANGENOMMEN");
    }

    @Test
    void liste_returnsAuftraegeFromService_withNullStatus() {
        List<Auftrag> expected = Collections.emptyList();
        when(werkstattService.getAuftraege(null)).thenReturn(expected);

        List<Auftrag> result = controller.liste(null);

        assertThat(result).isEmpty();
        verify(werkstattService).getAuftraege(null);
    }

    @Test
    void einzeln_returnsOk_whenAuftragFound() {
        Auftrag auftrag = mock(Auftrag.class);
        when(werkstattService.getAuftrag(1L)).thenReturn(auftrag);

        ResponseEntity<Auftrag> response = controller.einzeln(1L);

        assertThat(response.getStatusCode()).isEqualTo(HttpStatus.OK);
        assertThat(response.getBody()).isEqualTo(auftrag);
    }

    @Test
    void einzeln_returnsNotFound_whenAuftragMissing() {
        when(werkstattService.getAuftrag(99L)).thenReturn(null);

        ResponseEntity<Auftrag> response = controller.einzeln(99L);

        assertThat(response.getStatusCode()).isEqualTo(HttpStatus.NOT_FOUND);
        assertThat(response.getBody()).isNull();
    }

    @Test
    void anlegen_returnsOk_withCreatedAuftrag() {
        Auftrag input = mock(Auftrag.class);
        Auftrag created = mock(Auftrag.class);
        when(werkstattService.neuerAuftrag(input)).thenReturn(created);

        ResponseEntity<?> response = controller.anlegen(input);

        assertThat(response.getStatusCode()).isEqualTo(HttpStatus.OK);
        assertThat(response.getBody()).isEqualTo(created);
    }

    @Test
    void anlegen_returnsServerError_whenServiceThrows() {
        Auftrag input = mock(Auftrag.class);
        when(werkstattService.neuerAuftrag(input)).thenThrow(new RuntimeException("Fehler beim Anlegen"));

        ResponseEntity<?> response = controller.anlegen(input);

        assertThat(response.getStatusCode()).isEqualTo(HttpStatus.INTERNAL_SERVER_ERROR);
        assertThat(response.getBody()).isEqualTo("Fehler beim Anlegen");
    }

    @Test
    void status_returnsOk_withUpdatedAuftrag() {
        Auftrag updated = mock(Auftrag.class);
        when(werkstattService.setzeStatus(5L, "FERTIG")).thenReturn(updated);

        ResponseEntity<?> response = controller.status(5L, "FERTIG");

        assertThat(response.getStatusCode()).isEqualTo(HttpStatus.OK);
        assertThat(response.getBody()).isEqualTo(updated);
    }

    @Test
    void status_returnsServerError_whenServiceThrows() {
        when(werkstattService.setzeStatus(5L, "UNBEKANNT")).thenThrow(new RuntimeException("Ungueltiger Status"));

        ResponseEntity<?> response = controller.status(5L, "UNBEKANNT");

        assertThat(response.getStatusCode()).isEqualTo(HttpStatus.INTERNAL_SERVER_ERROR);
        assertThat(response.getBody()).isEqualTo("Ungueltiger Status");
    }

    @Test
    void position_returnsOk_withCreatedPosition() {
        AuftragPosition input = mock(AuftragPosition.class);
        AuftragPosition created = mock(AuftragPosition.class);
        when(werkstattService.neuePosition(3L, input)).thenReturn(created);

        ResponseEntity<?> response = controller.position(3L, input);

        assertThat(response.getStatusCode()).isEqualTo(HttpStatus.OK);
        assertThat(response.getBody()).isEqualTo(created);
    }

    @Test
    void position_returnsServerError_whenServiceThrows() {
        AuftragPosition input = mock(AuftragPosition.class);
        when(werkstattService.neuePosition(3L, input)).thenThrow(new RuntimeException("Auftrag nicht gefunden"));

        ResponseEntity<?> response = controller.position(3L, input);

        assertThat(response.getStatusCode()).isEqualTo(HttpStatus.INTERNAL_SERVER_ERROR);
        assertThat(response.getBody()).isEqualTo("Auftrag nicht gefunden");
    }

    @Test
    void positionLoeschen_returnsOk_whenSuccessful() {
        doNothing().when(werkstattService).loeschePosition(7L);

        ResponseEntity<?> response = controller.positionLoeschen(7L);

        assertThat(response.getStatusCode()).isEqualTo(HttpStatus.OK);
        assertThat(response.getBody()).isNull();
        verify(werkstattService).loeschePosition(7L);
    }

    @Test
    void positionLoeschen_returnsServerError_whenServiceThrows() {
        doThrow(new RuntimeException("Position nicht gefunden")).when(werkstattService).loeschePosition(8L);

        ResponseEntity<?> response = controller.positionLoeschen(8L);

        assertThat(response.getStatusCode()).isEqualTo(HttpStatus.INTERNAL_SERVER_ERROR);
        assertThat(response.getBody()).isEqualTo("Position nicht gefunden");
    }

    @Test
    void anlegen_returnsServerError_withNullMessage_whenExceptionMessageIsNull() {
        Auftrag input = mock(Auftrag.class);
        when(werkstattService.neuerAuftrag(input)).thenThrow(new RuntimeException());

        ResponseEntity<?> response = controller.anlegen(input);

        assertThat(response.getStatusCode()).isEqualTo(HttpStatus.INTERNAL_SERVER_ERROR);
        assertThat(response.getBody()).isNull();
    }
}
